import { test, expect } from '@playwright/test';

test.describe('Homepage Hero Section Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should display hero section correctly on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 812 }); // iPhone X size
    const heroSection = page.getByRole('banner');
    await expect(heroSection).toBeVisible();
    await expect(heroSection).toHaveCSS('flex-direction', 'column');
    await expect(heroSection).toHaveCSS('text-align', 'center');
  });

  test('should display hero section correctly on desktop', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 720 }); // Desktop size
    const heroSection = page.getByRole('banner');
    await expect(heroSection).toBeVisible();
    await expect(heroSection).toHaveCSS('flex-direction', 'row');
    await expect(heroSection).toHaveCSS('text-align', 'left');
  });
});
